import React, { useState, useEffect, useRef } from 'react';
import { ThemeProvider, Frame, List, TitleBar, Button as React95Button } from '@react95/core';
import styled from 'styled-components';
import GlobalStyles from './GlobalStyles';

// Boot Screen Component
const BootScreen = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background-color: #1e1e1e;  // Dark background
  color: #ffffff;  // Light text
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: 'OMORI_GAME', monospace;
  font-size: 24px;
  z-index: 999;
  opacity: ${({ isVisible }) => (isVisible ? 1 : 0)};
  transition: opacity 1.5s ease-out;
  pointer-events: ${({ isVisible }) => (isVisible ? 'all' : 'none')};
`;

const backgroundImages = [
  "/images/wallpaper1.png",
  "/images/wallpaper2.png",
  "/images/wallpaper3.png", // Add more images as needed
];

// Content Container Component
const ContentContainer = styled.div`
  background-color: #1e1e1e;  // Dark background
  width: 100vw;
  height: 100vh;
  position: fixed;
  top: 0;
  left: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
`;

// Desktop Component
const Desktop = styled.div`
  background-color: #1e1e1e;  // Dark background
  height: 100vh;
  width: 100vw;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
`;

// Window Border Component
const WindowBorder = styled.div`
  padding: 8px;
  box-sizing: border-box;
  display: flex;
  justify-content: center;
  align-items: center;
  border: 3px solid #606060;  // Adjust as needed
  height: 90vh;
  width: 80vw;
  background-color: #2e2e2e;  // Darker background for windows
`;

// Windowed Environment Component
const WindowedEnvironment = styled.div`
  position: relative;
  background: linear-gradient(0deg, rgba(33,5,77,1) 0%, rgba(42,8,129,1) 30%, rgba(108,14,255,1) 100%);
  height: 100%;
  width: 100%;
  box-sizing: border-box;
  overflow: hidden;
`;

// Background Layers
const BackgroundContainer = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  z-index: 0;
  pointer-events: none;
`;

const BackgroundImageLayer = styled.div`
  position: absolute;
  top: 0;
  left: -20%;
  width: 140%;
  height: 100%;
  background-image: url(${props => props.$bgImage});
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  opacity: ${({ $isActive }) => ($isActive ? 1 : 0)};
  transition: opacity 1.5s ease-in-out;
  animation: slowSlide 30s ease-in-out infinite alternate;
  will-change: transform, opacity;

  @keyframes slowSlide {
    0% {
      transform: translate3d(-7%, 0, 0);
    }
    100% {
      transform: translate3d(7%, 0, 0);
    }
  }
`;

// Taskbar Component
const Taskbar = styled.div`
  background: #c3c7cb;  // Windows 95 light gray taskbar
  height: 40px;
  width: 100%;
  position: absolute;
  bottom: 0;
  left: 0;
  display: flex;
  align-items: center;
  padding: 0 6px;
  box-sizing: border-box;
  border-top: 2px solid #ffffff;
  box-shadow: inset 0 1px 0 #dfdfdf;
  z-index: 100;
`;

// Styled React95 Button Component
const StyledReact95Button = styled(React95Button)`
  && {
    margin-right: 6px;
    font-family: 'OMORI_GAME', monospace;
    font-size: 16px;
    height: 30px;
    padding: 2px 10px;
